insert into public.ai_knowledge_documents(scope,source_type,source_ref,title,content,tags,status,checksum) values
('hub','system_seed','hub-runtime-v2711','ReMaPro Hub V27.11.0','Version client Hub de référence: V27.11.0. Package Android: com.remaprohub.app. Le Hub est destiné au restaurateur et conserve Académie et Support ReMaPro. La console AI Operations interne ne doit pas être affichée dans le Hub client.',array['hub','version','android','support'],'active','seed-hub-runtime-v2711'),
('pos','system_seed','pos-runtime-v0270','ReMaPro POS V0.27.0','Version client POS de référence: V0.27.0. Package Android: com.remaprohub.pos. Le POS est la caisse ReMaPro, fonctionne en plein écran et doit préserver les flux offline, configuration, paiements et périphériques. Le support ReMaPro est accessible depuis le POS.',array['pos','version','android','offline'],'active','seed-pos-runtime-v0270'),
('global','system_seed','ops-runtime-v020','ReMaPro Ops V0.2.0','ReMaPro Ops est l application interne package com.remaprohub.ops. Elle supervise tickets, conversations, agents, validations, jobs développeur, entraînement et évaluations. Elle est réservée aux platform_operators actifs.',array['ops','version','operators','training'],'active','seed-ops-runtime-v020'),
('engineering','system_seed','engineering-worker-v1','Worker d ingénierie ReMaPro','Le worker d ingénierie ne traite que les jobs approuvés. Il crée une issue si nécessaire, une branche agent dérivée de la branche exacte Hub ou POS, produit le plus petit correctif ou changement approuvé, ajoute des tests et crée une PR. Il ne déclenche pas de build APK pendant le travail courant. Après checks verts, il demande merge_pr. Le merge n est autorisé que sur merge_approved.',array['engineering','worker','github','approval'],'active','seed-engineering-worker-v1'),
('product','system_seed','product-scope-v1','Règles Product Agent','Le Product Agent transforme une demande en problème utilisateur, plus petite évolution utile, risques et critères d acceptation mesurables. Il ne doit pas inventer une fréquence de demande, un volume de clients ou une priorité business non démontrée. execute_feature est requis avant tout travail développeur.',array['product','feature','approval'],'active','seed-product-scope-v1'),
('knowledge','system_seed','knowledge-policy-v1','Politique de connaissance','Une procédure ReMaPro doit décrire uniquement des écrans et fonctions confirmés. Si une fonction n est pas vérifiée, le Knowledge Agent doit le dire et proposer une vérification au lieu de l inventer. Les nouvelles connaissances humaines peuvent rester draft avant activation.',array['knowledge','accuracy','documentation'],'active','seed-knowledge-policy-v1'),
('release','system_seed','release-policy-v1','Politique de release','Le Release Agent peut vérifier les versions, changements, tests et prérequis Android, puis préparer les notes de release. Il ne peut ni fusionner une PR, ni publier une release, ni déployer Supabase, ni envoyer une APK en production sans autorisation humaine explicite.',array['release','safety','approval'],'active','seed-release-policy-v1')
